22	// scanComments consumes the comment at the current position, along with
23	// any following lines that hold only blanks and comments, and records them.
24	// A comment right below content is a foot comment of that content, unless
25	// an empty line follows it; the others are head comments of what follows.
26	func (p *parser) scanComments(scanMark mark) bool {
27		last := p.tokens[len(p.tokens)-1]
28		if last.typ == tokFlowEntry && len(p.tokens) > 1 {
29			last = p.tokens[len(p.tokens)-2]
30		}
31		tokenMark := last.start
32		var startMark mark
33		nextIndent := max(p.indent, 0)
34		recentEmpty := false
35		firstEmpty := p.newlines <= 1
36		line, column := p.mark.line, p.mark.column
37		var text []byte
38	
39		// A comment starting on the foot line is still a foot of the prior
40		// content. If the current line has content, that is the line below it.
41		footLine := -1
42		if scanMark.line > 0 {
43			footLine = p.mark.line - p.newlines + 1
44			if p.newlines == 0 && p.mark.column > 1 {
45				footLine++
46			}
47		}
48	
49		// addFoot records the comment so far as a foot comment; what follows
50		// is taken by the tokens from end on.
51		addFoot := func(end mark) {
52			p.comments = append(p.comments, comment{tokenMark: tokenMark, startMark: startMark, foot: text})
53			tokenMark, text = end, nil
54		}
55	
56		peek := 0
57		for ; peek < 512; peek++ {
58			if p.unread < peek+1 && !p.updateBuffer(peek+1) {
59				break
60			}
61			column++
62			if p.isBlank(peek) {
63				continue
64			}
65			c := p.at(peek)
66			closeFlow := p.flowLevel > 0 && (c == ']' || c == '}')
67			if closeFlow || p.isBreakz(peek) {
68				// A line break or the end of a flow collection.
69				if closeFlow || !recentEmpty {
70					if closeFlow || firstEmpty && (startMark.line == footLine && last.typ != tokValue || startMark.column-1 < nextIndent) {
71						// The comment so far is a foot of the prior content.
72						if len(text) > 0 {
73							if startMark.column-1 < nextIndent {
74								// Dedented, it is unrelated to the prior token.
75								tokenMark = startMark
76							}
77							addFoot(mark{p.mark.index + peek, line, column})
78						}
